import{_ as d,o as e,c as s,aO as a}from"./chunks/framework.vjUPZZJn.js";const b=JSON.parse('{"title":"gdb 常用命令速查","description":"","frontmatter":{"date":"2026-09-15T12:00:00.000Z","title":"gdb 常用命令速查","source":[["1-知识/工具/调试/gdb 常用命令"]],"tags":["工具","教程手册","gdb","调试"],"categories":["工具"],"permalink":"/pages/fe5bec"},"headers":[],"relativePath":"工具/gdb 常用命令速查.md","filePath":"工具/gdb 常用命令速查.md","lastUpdated":1789451739000}'),i={name:"工具/gdb 常用命令速查.md"};function c(o,t,n,r,l,p){return e(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="gdb-常用命令速查" tabindex="-1">gdb 常用命令速查 <a class="header-anchor" href="#gdb-常用命令速查" aria-label="Permalink to &quot;gdb 常用命令速查&quot;">​</a></h1> <p>按功能分类整理的 GDB 常用命令速查表，覆盖断点、单步、栈帧、内存查看等日常调试动作，附两个附加进程的实战用法：不进交互界面批量打印线程栈，以及解决 attach 时的 ptrace 权限问题。GDB 接受无歧义的命令前缀，并内置了一批单字母别名（如 <code>d</code> 即 <code>delete</code>、<code>h</code> 即 <code>help</code>），表中「简写」列即常用别名。</p> <h2 id="命令速查表" tabindex="-1">命令速查表 <a class="header-anchor" href="#命令速查表" aria-label="Permalink to &quot;命令速查表&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>类别</th> <th>命令</th> <th>简写</th> <th>说明</th></tr></thead> <tbody><tr><td>启动与退出</td> <td><code>gdb [可执行文件]</code></td> <td>—</td> <td>启动 GDB 并加载可执行文件</td></tr> <tr><td></td> <td><code>quit</code></td> <td><code>q</code></td> <td>退出 GDB</td></tr> <tr><td>运行控制</td> <td><code>run [args]</code></td> <td><code>r</code></td> <td>开始运行程序（可带参数）</td></tr> <tr><td></td> <td><code>start</code></td> <td>—</td> <td>启动程序并停在 main 函数开头</td></tr> <tr><td></td> <td><code>continue</code></td> <td><code>c</code></td> <td>继续运行直到下一个断点或结束</td></tr> <tr><td></td> <td><code>kill</code></td> <td>—</td> <td>终止正在调试的程序</td></tr> <tr><td>断点管理</td> <td><code>break [位置]</code></td> <td><code>b</code></td> <td>在指定位置设断点（函数名、行号、地址等）<br>例：<code>b main</code>、<code>b file.c:10</code></td></tr> <tr><td></td> <td><code>break [位置] if [条件]</code></td> <td>—</td> <td>设置条件断点</td></tr> <tr><td></td> <td><code>info breakpoints</code></td> <td><code>i b</code></td> <td>查看所有断点</td></tr> <tr><td></td> <td><code>delete [编号]</code></td> <td><code>d</code></td> <td>删除指定编号的断点（不带编号则删除所有）</td></tr> <tr><td></td> <td><code>disable [编号]</code></td> <td>—</td> <td>禁用断点</td></tr> <tr><td></td> <td><code>enable [编号]</code></td> <td>—</td> <td>启用断点</td></tr> <tr><td>单步执行</td> <td><code>step</code></td> <td><code>s</code></td> <td>单步进入（会进入函数内部）</td></tr> <tr><td></td> <td><code>next</code></td> <td><code>n</code></td> <td>单步跳过（不进入函数）</td></tr> <tr><td></td> <td><code>finish</code></td> <td>—</td> <td>执行完当前函数并返回</td></tr> <tr><td></td> <td><code>until [位置]</code></td> <td><code>u</code></td> <td>运行到指定行（常用于跳出循环）</td></tr> <tr><td>查看信息</td> <td><code>list [位置]</code></td> <td><code>l</code></td> <td>显示源代码（默认当前行附近）</td></tr> <tr><td></td> <td><code>print [表达式]</code></td> <td><code>p</code></td> <td>打印变量或表达式的值</td></tr> <tr><td></td> <td><code>display [表达式]</code></td> <td>—</td> <td>每次停住时自动显示表达式的值</td></tr> <tr><td></td> <td><code>info locals</code></td> <td>—</td> <td>显示当前作用域的局部变量</td></tr> <tr><td></td> <td><code>info args</code></td> <td>—</td> <td>显示当前函数的参数</td></tr> <tr><td></td> <td><code>info registers</code></td> <td><code>i r</code></td> <td>显示寄存器内容</td></tr> <tr><td>栈帧操作</td> <td><code>backtrace</code></td> <td><code>bt</code></td> <td>显示调用栈（函数调用链）</td></tr> <tr><td></td> <td><code>frame [编号]</code></td> <td><code>f</code></td> <td>切换到指定栈帧</td></tr> <tr><td></td> <td><code>up</code> / <code>down</code></td> <td>—</td> <td>向调用者方向（帧号增大）/ 向被调用方向（帧号减小）移动一帧</td></tr> <tr><td>内存与寄存器</td> <td><code>x/[数量][格式][单位] 地址</code></td> <td>—</td> <td>查看内存内容<br>例：<code>x/10wx 0x1234</code>（10 个十六进制字）</td></tr> <tr><td></td> <td><code>set variable var = value</code></td> <td>—</td> <td>修改变量的值</td></tr> <tr><td>其他实用命令</td> <td><code>help [命令]</code></td> <td><code>h</code></td> <td>获取帮助</td></tr> <tr><td></td> <td><code>shell [命令]</code></td> <td>—</td> <td>在 GDB 中执行 shell 命令</td></tr> <tr><td></td> <td><code>set args [参数]</code></td> <td>—</td> <td>设置程序运行参数（等效于 run 时传参）</td></tr> <tr><td></td> <td><code>show args</code></td> <td>—</td> <td>显示当前设置的程序参数</td></tr></tbody></table> <blockquote><p>大多数命令支持 Tab 自动补全；<code>commands [编号]</code> 可为断点挂一组自动执行的命令；<code>layout src</code> 进入 TUI 模式，分屏显示源码和命令。</p></blockquote> <h2 id="附加进程打印全部线程栈" tabindex="-1">附加进程打印全部线程栈 <a class="header-anchor" href="#附加进程打印全部线程栈" aria-label="Permalink to &quot;附加进程打印全部线程栈&quot;">​</a></h2> <p>不进入交互界面，一次性抓取目标进程所有线程的调用栈（排查死锁、卡顿时常用）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;thread apply all bt&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PID</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="附加进程的-ptrace-权限问题" tabindex="-1">附加进程的 ptrace 权限问题 <a class="header-anchor" href="#附加进程的-ptrace-权限问题" aria-label="Permalink to &quot;附加进程的 ptrace 权限问题&quot;">​</a></h2> <p>Linux（Ubuntu 等发行版）默认开启 Yama 限制，GDB 附加非子进程时会报 <code>ptrace: Operation not permitted</code>。永久放开（降低了安全防护，仅建议在调试机上使用）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编辑 sysctl 配置文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/10-ptrace.conf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 修改为</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kernel.yama.ptrace_scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应用配置</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/10-ptrace.conf</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>临时放开（重启失效）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/kernel/yama/ptrace_scope</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>断点看 <code>i b</code>、删断点 <code>d N</code>、条件断点 <code>break ... if cond</code>，三个组合覆盖大部分断点需求</li> <li>排查崩溃先 <code>bt</code> 看调用栈，再 <code>f N</code> 切帧、<code>info locals</code> 看现场</li> <li>附加线上进程优先用 <code>gdb -batch -ex &quot;thread apply all bt&quot; -p PID</code>，一次输出全部线程栈，侵入最小</li></ul>`,26)])])}const k=d(i,[["render",c]]);export{b as __pageData,k as default};
